    {
      "步骤序号": 6,
      "操作": "第二次留固离心并水洗",
      "试剂/对象": "第一次水洗后的 K-rich FeHCF 固体、去离子水、进样瓶",
      "参数": "执行留固离心，6000 rpm，10 min，倒去上清液；加入去离子水 20 mL 重悬固体，完成第 2 次水洗。"
    },
    {
      "步骤序号": 7,
      "操作": "第三次留固离心并水洗",
      "试剂/对象": "第二次水洗后的 K-rich FeHCF 固体、去离子水、进样瓶",
      "参数": "执行留固离心，6000 rpm，10 min，倒去上清液；加入去离子水 20 mL 重悬固体，完成第 3 次水洗。"
